export circuit castVote(
  secretKey: witness<Field>,
  merkleProof: [Field; depth],
  vote: Field,
  nullifier: Field,
  root: Field
) {
  // 1. Elegibilidad
  const leaf = hash(secretKey);
  assert(verifyMerkle(leaf, merkleProof, root));

  // 2. Unicidad
  assert(!usedNullifiers.member(nullifier));
  usedNullifiers.insert(nullifier);

  // 3. Commitment de voto válido
  assert(verifyCommitment(vote, commitment));
}

